import{_ as o,o as a,c as t,ag as i}from"./chunks/framework.VvOSaRrC.js";const u=JSON.parse('{"title":"kroot 브라우저 기반 PAT 로그인 — 설계 문서","description":"","frontmatter":{},"headers":[],"relativePath":"specs/2026-06-23-kroot-browser-pat-login-design.md","filePath":"specs/2026-06-23-kroot-browser-pat-login-design.md"}'),c={name:"specs/2026-06-23-kroot-browser-pat-login-design.md"};function d(n,e,r,l,s,p){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="kroot-브라우저-기반-pat-로그인-—-설계-문서" tabindex="-1">kroot 브라우저 기반 PAT 로그인 — 설계 문서 <a class="header-anchor" href="#kroot-브라우저-기반-pat-로그인-—-설계-문서" aria-label="Permalink to &quot;kroot 브라우저 기반 PAT 로그인 — 설계 문서&quot;">​</a></h1><ul><li>날짜: 2026-06-23</li><li>상태: 설계 확정 대기(사용자 리뷰 후 구현 계획으로)</li><li>범위: <code>kroot-adk</code>(CLI, Go) + <code>kroot/backend/server/auth</code>(Spring Authorization Server). <code>kroot-server</code>(Go/gRPC)는 <strong>변경 없음</strong>.</li></ul><h2 id="_1-목표" tabindex="-1">1. 목표 <a class="header-anchor" href="#_1-목표" aria-label="Permalink to &quot;1. 목표&quot;">​</a></h2><p><code>kroot init</code> / <code>kroot auth login</code>의 인증을 이메일+비밀번호 대화형에서 <strong>브라우저 기반 로그인</strong>(Claude Code / Codex 구독 로그인 방식)으로 전환한다. 데스크톱은 loopback 리디렉션, 헤드리스/SSH는 device 코드 플로우로 지원한다. 발급되는 자격증명은 기존 <strong>PAT(<code>kpat_</code>)</strong> 를 재사용한다.</p><h3 id="확정된-결정" tabindex="-1">확정된 결정 <a class="header-anchor" href="#확정된-결정" aria-label="Permalink to &quot;확정된 결정&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>결정</th><th>값</th></tr></thead><tbody><tr><td>Q1</td><td>실행 환경</td><td>loopback + device 폴백 <strong>둘 다</strong></td></tr><tr><td>Q2</td><td>이메일+비번</td><td><strong>완전 제거</strong>. 자동화/CI는 <code>--token</code> / <code>KROOT_TOKEN</code></td></tr><tr><td>Q3</td><td>토큰 모델</td><td><strong>기존 PAT(<code>kpat_</code>) 재사용</strong> (kroot-server 검증 변경 0)</td></tr><tr><td>D1</td><td>PAT 만료</td><td><strong>90일 + CLI 자동 재발급(silent re-auth)</strong>. 서버 만료 모델 변경 없음</td></tr><tr><td>D2</td><td>헤드리스</td><td><strong>Device Authorization Grant(RFC 8628)를 인증 서버에 추가</strong></td></tr></tbody></table><h2 id="_2-현재-상태-코드-확인-결과" tabindex="-1">2. 현재 상태 (코드 확인 결과) <a class="header-anchor" href="#_2-현재-상태-코드-확인-결과" aria-label="Permalink to &quot;2. 현재 상태 (코드 확인 결과)&quot;">​</a></h2><h3 id="이미-존재-—-데스크톱-loopback은-서버-작업-0" tabindex="-1">이미 존재 — 데스크톱 loopback은 서버 작업 0 <a class="header-anchor" href="#이미-존재-—-데스크톱-loopback은-서버-작업-0" aria-label="Permalink to &quot;이미 존재 — 데스크톱 loopback은 서버 작업 0&quot;">​</a></h3><p>인증 서버 <code>kroot/backend/server/auth</code>(포트 17020):</p><ul><li>OAuth2 Authorization Server: <code>/authorize</code>, <code>/token</code>, <code>formLogin</code> <code>/login</code> 페이지.</li><li><strong><code>kroot-cli-app</code> public 클라이언트</strong>(application-dev.yml): <code>public-client: true</code>(PKCE), <code>grant-types: [authorization_code]</code>, <code>redirect-uris: [http://127.0.0.1:17298/callback]</code>, <code>scopes: [openid, profile, email]</code>. 주석에 본 설계 흐름이 그대로 명시됨.</li><li><strong><code>POST /api/me/credentials</code></strong>(<code>PatController</code>): 인증된 사용자가 PAT 발급. 요청 <code>{name, scopes, expiresDays}</code>, 응답 <code>{id, token(평문 1회), tokenPrefix, expiresAt}</code>. form 세션 / Bearer JWT / PAT 인증 모두 허용(<code>CurrentUser</code>).</li><li><code>PatService.issue(...)</code>: <code>DEFAULT_EXPIRES_DAYS=90</code>, <code>MAX_EXPIRES_DAYS=90</code>(초과 시 clamp), <code>PER_USER_QUOTA=5</code>. <code>ALLOWED_SCOPES</code>에 <code>kroot.cli.read</code>, <code>kroot.cli.write</code> 포함.</li><li>PAT introspection(<code>/api/internal/pat/introspect</code>): <code>kroot-server</code>가 이미 호출(M2M client <code>kroot-server</code>).</li></ul><h3 id="없음-—-추가-필요" tabindex="-1">없음 — 추가 필요 <a class="header-anchor" href="#없음-—-추가-필요" aria-label="Permalink to &quot;없음 — 추가 필요&quot;">​</a></h3><ul><li><strong>Device Authorization Grant</strong>: <code>kroot-cli-app</code>은 loopback authorization_code 전용. device 엔드포인트·검증 페이지 없음. (D2)</li></ul><h3 id="cli-현재-상태-kroot-adk" tabindex="-1">CLI 현재 상태 (<code>kroot-adk</code>) <a class="header-anchor" href="#cli-현재-상태-kroot-adk" aria-label="Permalink to &quot;CLI 현재 상태 (\`kroot-adk\`)&quot;">​</a></h3><ul><li><code>cmd/authcmd/login.go</code>: 이메일+비번 또는 <code>--token kpat_…</code>(저장 후 종료). OS 키체인 저장 존재.</li><li><code>cmd/initcmd/backend.go</code>: <code>loginInteractive</code>(이메일+비번 대화형).</li><li><code>cmd/authcmd/{logout,token,whoami}.go</code>, <code>status.go</code> 존재.</li></ul><h2 id="_3-아키텍처-인증-흐름" tabindex="-1">3. 아키텍처 / 인증 흐름 <a class="header-anchor" href="#_3-아키텍처-인증-흐름" aria-label="Permalink to &quot;3. 아키텍처 / 인증 흐름&quot;">​</a></h2><h3 id="_3-1-loopback-데스크톱-기본" tabindex="-1">3.1 Loopback (데스크톱 기본) <a class="header-anchor" href="#_3-1-loopback-데스크톱-기본" aria-label="Permalink to &quot;3.1 Loopback (데스크톱 기본)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>kroot init | kroot auth login</span></span>
<span class="line"><span> 1. CLI: 127.0.0.1:17298 콜백 서버 기동 (포트 사용 중이면 D2 폴백 또는 대체 포트는 §7)</span></span>
<span class="line"><span> 2. CLI: PKCE code_verifier/code_challenge + state(난수) 생성</span></span>
<span class="line"><span> 3. CLI: 브라우저 오픈 → GET {issuer}/authorize</span></span>
<span class="line"><span>        ?response_type=code&amp;client_id=kroot-cli-app</span></span>
<span class="line"><span>        &amp;redirect_uri=http://127.0.0.1:17298/callback</span></span>
<span class="line"><span>        &amp;scope=openid profile email&amp;state=&lt;state&gt;</span></span>
<span class="line"><span>        &amp;code_challenge=&lt;chal&gt;&amp;code_challenge_method=S256</span></span>
<span class="line"><span> 4. 사용자: 기존 /login 폼으로 로그인 (+ 최초 동의)</span></span>
<span class="line"><span> 5. 서버: 302 → http://127.0.0.1:17298/callback?code=&lt;code&gt;&amp;state=&lt;state&gt;</span></span>
<span class="line"><span> 6. CLI: state 검증 → POST {issuer}/token (code + code_verifier) → access_token(JWT, 단기)</span></span>
<span class="line"><span> 7. CLI: POST {issuer}/api/me/credentials  (Authorization: Bearer &lt;access_token&gt;)</span></span>
<span class="line"><span>        body {name:&quot;cli@&lt;hostname&gt;&quot;, scopes:[&quot;kroot.cli.read&quot;,&quot;kroot.cli.write&quot;], expiresDays:90}</span></span>
<span class="line"><span>        → {token:&quot;kpat_…&quot;, expiresAt}</span></span>
<span class="line"><span> 8. CLI: kpat_ 를 OS 키체인에 저장 (기존 --token 저장 경로 재사용) + expiresAt 메타 기록</span></span>
<span class="line"><span> 9. 브라우저에 &quot;로그인 완료, 터미널로 돌아가세요&quot; 페이지 표시</span></span></code></pre></div><p>access_token 은 PAT 발급에만 쓰고 버린다(저장하지 않음). 장수명 자격은 PAT.</p><h3 id="_3-2-device-코드-헤드리스-ssh-—-d2" tabindex="-1">3.2 Device 코드 (헤드리스/SSH) — D2 <a class="header-anchor" href="#_3-2-device-코드-헤드리스-ssh-—-d2" aria-label="Permalink to &quot;3.2 Device 코드 (헤드리스/SSH) — D2&quot;">​</a></h3><p>서버에 Device Authorization Grant 추가 후:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>kroot auth login --device  (또는 브라우저 오픈 실패 시 자동 폴백)</span></span>
<span class="line"><span> 1. CLI: POST {issuer}/oauth2/device_authorization (client_id=kroot-cli-app, scope=...)</span></span>
<span class="line"><span>        → {device_code, user_code, verification_uri, verification_uri_complete, interval, expires_in}</span></span>
<span class="line"><span> 2. CLI: 터미널 표시 &quot;브라우저에서 {verification_uri} 열고 코드 {user_code} 입력&quot;</span></span>
<span class="line"><span>        (가능하면 QR/verification_uri_complete 도)</span></span>
<span class="line"><span> 3. 사용자: 다른 기기 브라우저에서 로그인 + user_code 승인(동의)</span></span>
<span class="line"><span> 4. CLI: POST {issuer}/token (grant_type=device_code, device_code) 를 interval 간격 폴링</span></span>
<span class="line"><span>        → authorization_pending / slow_down / access_denied / expired_token 표준 처리</span></span>
<span class="line"><span>        → 승인되면 access_token</span></span>
<span class="line"><span> 5. 이후 §3.1 의 7~8 과 동일(/api/me/credentials → kpat_ → 키체인)</span></span></code></pre></div><h3 id="_3-3-자동-재발급-silent-re-auth-—-d1" tabindex="-1">3.3 자동 재발급 (silent re-auth) — D1 <a class="header-anchor" href="#_3-3-자동-재발급-silent-re-auth-—-d1" aria-label="Permalink to &quot;3.3 자동 재발급 (silent re-auth) — D1&quot;">​</a></h3><ul><li>CLI는 저장 시 PAT 의 <code>expiresAt</code> 를 함께 보관.</li><li>명령 실행 전 또는 gRPC가 PAT 만료로 <code>Unauthenticated</code> 반환 시: <ul><li>만료 임박(예: &lt; 3일) 또는 만료됨 → §3.1/§3.2 플로우를 <strong>자동 1회 재실행</strong>해 새 PAT 발급·교체.</li><li>비대화형(CI, <code>KROOT_TOKEN</code>/<code>--token</code>) 환경에서는 자동 재인증을 시도하지 않고 명확한 에러 + 안내.</li></ul></li><li>결과적으로 사용자 체감은 &quot;만료 없음&quot;이되 서버의 90일 만료/회전 보안은 유지.</li></ul><h2 id="_4-컴포넌트별-변경" tabindex="-1">4. 컴포넌트별 변경 <a class="header-anchor" href="#_4-컴포넌트별-변경" aria-label="Permalink to &quot;4. 컴포넌트별 변경&quot;">​</a></h2><h3 id="_4-1-cli-kroot-adk-go" tabindex="-1">4.1 CLI (<code>kroot-adk</code>, Go) <a class="header-anchor" href="#_4-1-cli-kroot-adk-go" aria-label="Permalink to &quot;4.1 CLI (\`kroot-adk\`, Go)&quot;">​</a></h3><ul><li><strong>신규</strong> <code>internal/auth/browserlogin/</code>(또는 유사): <ul><li><code>loopback.go</code> — 콜백 HTTP 서버, 포트 17298(점유 시 §7), 완료 페이지.</li><li><code>pkce.go</code> — code_verifier/challenge(S256), state 난수.</li><li><code>browser.go</code> — <code>open</code>/<code>xdg-open</code>/<code>rundll32</code> 브라우저 오픈(실패 감지 → device 폴백).</li><li><code>device.go</code> — device_authorization 요청 + 폴링(<code>interval</code>/<code>slow_down</code> 준수).</li><li><code>flow.go</code> — access_token 획득 → <code>/api/me/credentials</code> 호출 → PAT 반환(loopback/device 공통).</li></ul></li><li><strong>수정</strong> <code>cmd/authcmd/login.go</code>: 이메일+비번 제거. 기본 = 브라우저 플로우. <code>--device</code> 강제 device. <code>--token</code>/<code>KROOT_TOKEN</code> 유지(CI). 성공 시 키체인 저장.</li><li><strong>수정</strong> <code>cmd/initcmd/backend.go</code>: <code>loginInteractive</code>(이메일+비번) → 브라우저 플로우 호출. <code>promptPassword</code>·이메일 프롬프트 제거.</li><li><strong>수정</strong> 토큰 저장소: PAT + <code>expiresAt</code> 메타 저장(자동 재발급 판단용). 기존 키체인 추상화 확장.</li><li><strong>수정</strong> <code>cmd/authcmd/logout.go</code>: 키체인 PAT 삭제 + 가능하면 <code>DELETE /api/me/credentials/{id}</code>로 서버 revoke.</li><li><strong>설정</strong>: issuer 는 서버 discovery(<code>auth_discovery</code>)에서 가져옴 — CLI에 하드코딩하지 않음. client_id <code>kroot-cli-app</code>, redirect 포트 17298 는 상수/설정.</li></ul><h3 id="_4-2-인증-서버-kroot-backend-server-auth-spring-—-d2만" tabindex="-1">4.2 인증 서버 (<code>kroot/backend/server/auth</code>, Spring) — D2만 <a class="header-anchor" href="#_4-2-인증-서버-kroot-backend-server-auth-spring-—-d2만" aria-label="Permalink to &quot;4.2 인증 서버 (\`kroot/backend/server/auth\`, Spring) — D2만&quot;">​</a></h3><ul><li>Device Authorization Grant 활성화(Spring Authorization Server <code>OAuth2AuthorizationServerConfigurer</code> device 지원): <ul><li><code>kroot-cli-app</code>(또는 전용 device 클라이언트)에 <code>urn:ietf:params:oauth:grant-type:device_code</code> grant 추가.</li><li><code>/oauth2/device_authorization</code> 엔드포인트 노출.</li><li><strong>device 검증 UI</strong> 페이지(user_code 입력/승인) — 기존 <code>/login</code> 세션 재사용.</li><li>보안 체인(<code>DefaultSecurityConfig</code>)에 device 엔드포인트·검증 페이지 경로 허용.</li></ul></li><li>PAT 발급/검증/만료 모델은 <strong>변경 없음</strong>(D1=b 채택으로 무기한 PAT 불필요).</li></ul><h3 id="_4-3-kroot-server-go-grpc" tabindex="-1">4.3 kroot-server (Go/gRPC) <a class="header-anchor" href="#_4-3-kroot-server-go-grpc" aria-label="Permalink to &quot;4.3 kroot-server (Go/gRPC)&quot;">​</a></h3><ul><li><strong>변경 없음.</strong> <code>CompositeVerifier</code> + <code>SpringPATVerifier</code> introspection 이 이미 <code>kpat_</code> 수용.</li></ul><h2 id="_5-데이터-토큰-정책" tabindex="-1">5. 데이터 / 토큰 / 정책 <a class="header-anchor" href="#_5-데이터-토큰-정책" aria-label="Permalink to &quot;5. 데이터 / 토큰 / 정책&quot;">​</a></h2><ul><li>PAT <code>name</code>: <code>cli@&lt;hostname&gt;</code> (기기 식별). 동일 기기 재로그인 시 기존 동일-name PAT 를 revoke 후 재발급(quota 보호).</li><li>scopes: <code>kroot.cli.read</code>, <code>kroot.cli.write</code>.</li><li><code>PER_USER_QUOTA=5</code>: 재로그인이 quota 초과를 유발하지 않도록 자기 기기 PAT 정리. 초과 시 사용자에게 목록·revoke 안내.</li><li>키체인 저장 키: 기존 스킴 유지(이슈어/사용자별).</li></ul><h2 id="_6-보안-고려" tabindex="-1">6. 보안 고려 <a class="header-anchor" href="#_6-보안-고려" aria-label="Permalink to &quot;6. 보안 고려&quot;">​</a></h2><ul><li>PAT 평문은 발급 응답 1회만, 키체인에만 저장(로그/파일 평문 금지).</li><li>loopback: <code>state</code> + PKCE(S256)로 코드 인터셉트/CSRF 방지. redirect_uri 정확 매칭(127.0.0.1:17298).</li><li>device: <code>interval</code> 준수, <code>slow_down</code> 백오프, <code>expires_in</code> 후 만료. user_code 충분한 엔트로피(서버 기본).</li><li>access_token 은 저장하지 않음(PAT 발급에만 사용).</li><li><code>logout</code> 은 서버 revoke 까지 시도해 분실 기기 차단.</li><li>자동 재발급은 대화형에서만(비대화형은 명시적 실패).</li></ul><h2 id="_7-에러-엣지" tabindex="-1">7. 에러 / 엣지 <a class="header-anchor" href="#_7-에러-엣지" aria-label="Permalink to &quot;7. 에러 / 엣지&quot;">​</a></h2><ul><li>포트 17298 점유: 등록된 redirect_uri 가 고정이라 임의 포트는 불가 → (1) 짧게 대기 후 재시도, (2) 그래도 안 되면 <strong>device 폴백</strong> 안내. (대체 포트를 쓰려면 서버 redirect_uri 추가 등록 필요 — §13.)</li><li>브라우저 오픈 실패(헤드리스) → device 폴백 자동.</li><li>state 불일치 / code 만료 → 거부 + 재시도.</li><li>device: <code>authorization_pending</code>(계속 폴링), <code>slow_down</code>(interval 증가), <code>access_denied</code>(중단), <code>expired_token</code>(재시작 안내).</li><li>quota 초과(5개) → 활성 PAT 목록 표시 + revoke 안내.</li><li>네트워크/서버 다운 → 명확한 메시지, 키체인 기존 토큰 보존.</li></ul><h2 id="_8-테스트-전략" tabindex="-1">8. 테스트 전략 <a class="header-anchor" href="#_8-테스트-전략" aria-label="Permalink to &quot;8. 테스트 전략&quot;">​</a></h2><ul><li>CLI 단위: PKCE 생성, state 검증, 콜백 파싱, device 폴링 상태머신(pending/slow_down/denied/expired), 자동 재발급 트리거(만료 임박/401), 비대화형 비-재인증.</li><li>CLI 통합: 모의 인증 서버(<code>/authorize</code>,<code>/token</code>,<code>/api/me/credentials</code>,<code>/oauth2/device_authorization</code>)로 loopback·device E2E.</li><li>서버: device grant 발급·승인·폴링·만료 통합 테스트(기존 <code>OAuth2TestClient</code> 패턴 확장).</li><li>회귀: <code>--token</code>/<code>KROOT_TOKEN</code> CI 경로 유지 확인. 이메일+비번 제거로 깨지는 호출부 정리.</li></ul><h2 id="_9-범위-밖-후속" tabindex="-1">9. 범위 밖 / 후속 <a class="header-anchor" href="#_9-범위-밖-후속" aria-label="Permalink to &quot;9. 범위 밖 / 후속&quot;">​</a></h2><ul><li>무기한 PAT(서버 만료 모델 변경) — D1=b 로 제외.</li><li>refresh_token 회전 기반 모델(Q3-2) — 제외.</li><li>대체 loopback 포트 동적 등록.</li></ul><h2 id="_10-미해결-질문-구현-전-확인" tabindex="-1">10. 미해결 질문(구현 전 확인) <a class="header-anchor" href="#_10-미해결-질문-구현-전-확인" aria-label="Permalink to &quot;10. 미해결 질문(구현 전 확인)&quot;">​</a></h2><ol><li>redirect 포트 <strong>17298 고정</strong> 유지 가정(점유 시 device 폴백). 동적 포트가 필요하면 서버 redirect_uri 정책 변경 필요.</li><li>device 검증 UI 의 디자인/문구(기존 <code>/login</code> 테마 재사용 가정).</li><li><code>kroot logout</code> 서버 revoke 의 PAT id 확보 방법(발급 시 <code>id</code> 저장 가정).</li></ol>`,42)])])}const k=o(c,[["render",d]]);export{u as __pageData,k as default};
